func validateRouteWiring(cfg map[string]interface{}, steps map[string]models.Step) error {
	if len(steps) == 0 { return nil }            // fail OPEN: no plan visible
	routeOutputFields := map[string]bool{}
	for _, st := range steps {
		if st.Action == "diagnose_route" { routeOutputFields[st.OutputField] = true }
	}
	if len(routeOutputFields) == 0 { return nil } // no route step -> nothing forwards here
	coupled := [][2]string{
		{"data_requests_field", "route.data_requests"},
		{"code_requests_field", "route.code_requests"},
		{"data_requests_dropped_field", routeOutputPrefix + dataRequestsDroppedKey},
		{"code_requests_dropped_field", routeOutputPrefix + codeRequestsDroppedKey},
	}
	for _, c := range coupled {
		field := datahelpers.GetStringField(cfg, c[0], c[1])
		prefix := field
		if i := strings.IndexByte(field, '.'); i >= 0 { prefix = field[:i] }
		if !routeOutputFields[prefix] {
			return fmt.Errorf("diagnose_load_runtime: route wiring mismatch -- %s=%q reads namespace %q, but no diagnose_route step writes under that output_field (present: %s). A forwarded request or upstream drop would read as absent and be silently counted as zero; align the diagnose_route step's output_field with this reader's %s.", c[0], field, prefix, sortedQuotedKeys(routeOutputFields), c[0])
		}
	}
	return nil
}

