func TestValidateRouteWiring(t *testing.T) {
	routeStep := func(of string) models.Step { return models.Step{Action: "diagnose_route", OutputField: of} }
	// divergent override fails loudly:
	steps := map[string]models.Step{"route": routeStep("myroute")} // reader on route.* defaults
	err := validateRouteWiring(map[string]interface{}{}, steps)
	if err == nil { t.Fatal("an output_field override with the reader on defaults must fail") }
	if !strings.Contains(err.Error(), "wiring mismatch") || !strings.Contains(err.Error(), `"myroute"`) {
		t.Fatalf("error must name the mismatch and the present namespace: %v", err)
	}
	// + consistent-override pass, partial-override fail, empty-output_field fail,
	// no-route skip, nil-steps fail-open (see file for all seven subtests)
}
